repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('river', 49), ('hill', 22), ('upper', 42), ('river', 43), ('upper', 12), ('lower', 39)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.search.py:
"""Finding harvests by field."""


def harvests_for(harvests, field):
    """Return the harvests whose field matches, ignoring upper and lower case and spaces at either end."""
    return [x for x in harvests if x.field == field]


def has_field(harvests, field):
    """Return True when at least one harvest matches the field."""
    return len(harvests_for(harvests, field)) > 0


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names


def group_by_field(harvests):
    """Return a dict from field to the list of harvests with that field."""
    groups = {}
    for x in harvests:
        groups.setdefault(x.field, []).append(x)
    return groups
